<template><div class="page-shell"><header class="page-header"><p class="eyebrow">Guided learning paths</p><h1>Courses</h1><p>Explore a grade or continue with a skill that matches your goals.</p></header><p v-if="error" class="error-state">{{error}}</p><div class="courses"><article v-for="course in courses" :key="course.id" class="glass-card course"><button class="course-head" @click="open=open===course.id?null:course.id" :aria-expanded="open===course.id"><span class="grade">{{course.grade}}</span><span><small>Grade {{course.grade}}</small><b>{{course.title}}</b><em>{{course.description}}</em></span><strong>{{open===course.id?'−':'+'}}</strong></button><div v-if="open===course.id" class="units"><section v-for="unit in course.units" :key="unit.id"><h3>{{unit.title}}</h3><p>{{unit.description}}</p><div class="skills"><article v-for="skill in unit.skills" :key="skill.code"><div><b>{{skill.title}}</b><span class="status">{{skill.masteryStatus.replace('_',' ')}}</span></div><p>{{skill.introduction}}</p><details><summary>Example and hint</summary><p>{{skill.workedExample}}</p><p><strong>Hint:</strong> {{skill.hint}}</p></details><router-link class="button secondary" :to="`/drills?skill=${skill.code}`">Practice</router-link></article></div></section></div></article></div></div></template>
<script>import{api}from'../api';export default{name:'Courses',data:()=>({courses:[],open:null,error:''}),async created(){document.title='Courses · Math Practice';try{this.courses=await api('/api/courses');this.open=this.courses.find(c=>c.grade===4)?.id||this.courses[0]?.id}catch(e){this.error=e.message}}}</script>
<style scoped>.courses{display:grid;gap:1rem;padding-bottom:4rem}.course{overflow:hidden}.course-head{width:100%;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:1.2rem;text-align:left;padding:1.4rem;border:0;background:transparent;color:var(--clr-text);cursor:pointer}.grade{width:3.3rem;aspect-ratio:1;display:grid;place-items:center;border-radius:1rem;background:hsl(var(--clr-primary-400));font:800 1.5rem var(--ff-serif)}.course-head span:nth-child(2){display:grid}.course-head small{font:700 .7rem var(--ff-mono);color:hsl(var(--clr-accent-200));text-transform:uppercase}.course-head b{font:700 1.4rem var(--ff-serif)}.course-head em{font-style:normal;color:hsl(var(--clr-white-600))}.course-head>strong{font-size:2rem}.units{padding:0 1.5rem 1.5rem}.units>section{border-top:1px solid hsl(var(--clr-white-200)/.12);padding-top:1.5rem;margin-top:1rem}.units h3{font:700 1.3rem var(--ff-serif)}.units>section>p{color:hsl(var(--clr-white-600));margin:.25rem 0 1rem}.skills{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem}.skills>article{padding:1rem;border-radius:1rem;background:hsl(var(--clr-black-800)/.22);border:1px solid hsl(var(--clr-white-200)/.1)}.skills>article>div{display:flex;justify-content:space-between;gap:.5rem}.skills p{font-size:.88rem;margin:.7rem 0;color:hsl(var(--clr-white-400))}.skills details{margin-bottom:1rem}.skills summary{cursor:pointer;color:hsl(var(--clr-accent-200));font-size:.85rem}@media(max-width:45rem){.skills{grid-template-columns:1fr}.course-head em{display:none}}</style>
